"""Mechanically compare the translated program and the claim's executed term."""

from __future__ import annotations

from pathlib import Path


def strip_layout(text: str) -> str:
    output: list[str] = []
    quoted = False
    escaped = False
    for char in text:
        if quoted:
            output.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
        else:
            if char == '"':
                quoted = True
                output.append(char)
            elif not char.isspace():
                output.append(char)
    if quoted:
        raise ValueError("unterminated string")
    return "".join(output)


